package com.morphlabs.morph.core.academy.deck

import com.morphlabs.morph.core.academy.Action
import com.morphlabs.morph.core.academy.Card
import com.morphlabs.morph.core.academy.Signal
import com.morphlabs.morph.core.academy.Track

internal object FreedomCards {
    private val T = Track.FREEDOM
    val cards: List<Card> = listOf(
        // ── Level 1: Rookie (tops up the 14 starter cards) ──
        quiz("fr-passive-active", T, 1, "Which of these is passive income?",
            listOf("Your salary", "Interest from a money market fund", "Boda boda fares you ride for", "Overtime pay"), 1,
            "Active income needs your time. Passive income keeps coming when you stop: interest, dividends, rent, or a business others run."),
        concept("fr-freedom-choice", T, 1, "Does financial freedom mean you stop working forever?",
            "Not necessarily. It means work becomes optional: you can choose what, when and with whom. Many people keep building businesses or doing work they love, just without needing the paycheck."),

        // ── Level 2: Hustler ──
        quiz("fr-number-30", T, 2, "You spend Ksh 50,000 a month. At ×30 of yearly spending, your freedom number is…",
            listOf("Ksh 1.5M", "Ksh 15M", "Ksh 18M", "Ksh 25M"), 2,
            "Ksh 50,000 × 12 = Ksh 600,000 a year. × 30 = Ksh 18M. It's set by spending, not income, so lowering spending lowers the target."),
        quiz("fr-spend-cut", T, 2, "Cutting Ksh 5,000 a month from spending lowers a ×30 freedom number by…",
            listOf("Ksh 60,000", "Ksh 150,000", "Ksh 1.8M", "Ksh 5M"), 2,
            "5,000 × 12 × 30 = Ksh 1.8M less you need to build, plus Ksh 60,000 a year more to invest. Spending cuts work twice.",
            signals = setOf(Signal.OVER_BUDGET)),
        quiz("fr-rate-table", T, 2, "Starting from zero with 5% real returns and a ×30 target, saving 50% of income gets you free in about…",
            listOf("9 years", "19 years", "31 years", "40 years"), 1,
            "Our math: 10% → ~55 yrs, 20% → ~40, 30% → ~31, 50% → ~19, 70% → ~11. Higher savings means more invested and less to replace.",
            source = "Morph calculation, after \"The Shockingly Simple Math\" (MMM, 2012)"),
        concept("fr-why-rate", T, 2, "Why does savings rate matter more than income for reaching freedom?",
            "It does two jobs: it sets how much you invest, and it shows how little you need to live on. Someone earning Ksh 80k and saving half gets free faster than someone earning Ksh 300k and saving 10%."),
        concept("fr-lean-fat", T, 2, "What are Lean FI and Fat FI?",
            "Lean FI: assets cover a simple, basic lifestyle. Fat FI: they cover a comfortable one with travel and extras. Same formula, different spending. Many reach Lean first and keep working towards Fat."),
        quiz("fr-barista", T, 2, "\"Barista FI\" means…",
            listOf("Investments cover part of your costs; light work covers the rest", "You own a coffee shop", "You never work again", "You live off loans"), 0,
            "A part-time job or small hustle tops up investment income. It lowers the number you need and can start years earlier."),
        quiz("fr-coast-math", T, 2, "At 30 you have Ksh 2M invested. At 5% real a year untouched, by 60 it grows to about…",
            listOf("Ksh 5M", "Ksh 8.6M", "Ksh 3M", "Ksh 20M"), 1,
            "2M × 1.05^30 ≈ Ksh 8.6M in today's money. If your number is about that, you've hit Coast FI and only need to cover current costs."),
        concept("fr-streams", T, 2, "Why do people on the path to freedom build several income streams?",
            "One job is one point of failure. A salary plus a side business, rent, dividends or MMF interest means losing one doesn't stop everything, and extra streams speed up investing."),
        quiz("fr-first-stream", T, 2, "Which second income stream needs the least capital to start?",
            listOf("A rental flat", "A skill-based side service", "A matatu", "A petrol station"), 1,
            "Selling a skill (design, tutoring, repairs, bookkeeping) needs time more than money. Its profits can later fund capital-heavy streams."),
        concept("fr-raise-split", T, 2, "What's a simple rule for handling raises or windfalls on the path to freedom?",
            "Decide the split before the money lands, e.g. half to investing, a quarter to goals, a quarter to enjoy. You still feel richer, but your savings rate rises every time.",
            signals = setOf(Signal.MONEY_IN_RECENT)),
        you("fr-you-coast", T, 2, "Your net worth is {net_worth}, against a freedom number of {freedom_number}. Every year it compounds untouched, the gap shrinks without new work.",
            "Even small invested amounts matter early: at 5% real, money roughly doubles every 14 years.",
            tryThis = "Check your accounts and net worth.", action = Action.ACCOUNTS),

        // ── Level 3: Pro ──
        concept("fr-bengen", T, 3, "Where does the \"4% rule\" come from?",
            "William Bengen (1994) tested US history from 1926: withdrawing 4% of a stock/bond portfolio in year one, then raising it with inflation, never ran out in under about 30 years. The exact worst case was about 4.15%.",
            source = "Bengen, Journal of Financial Planning, 1994"),
        quiz("fr-trinity", T, 3, "The Trinity study (1998) tested withdrawal rates on US data. Its key insight was that…",
            listOf("Success depends on the rate, the mix and how long you need it", "Any rate works with enough stocks", "Bonds alone are safest", "4% lasts forever"), 0,
            "Cooley, Hubbard and Walz showed 4% worked in most 30-year periods for stock-heavy mixes, but higher rates and longer periods failed far more often.",
            source = "Cooley, Hubbard & Walz, AAII Journal, 1998"),
        quiz("fr-rule-inverse", T, 3, "A 3.5% withdrawal rate means your freedom number is about…",
            listOf("×25 spending", "×29 spending", "×35 spending", "×3.5 spending"), 1,
            "Multiple = 1 ÷ withdrawal rate: 1 ÷ 0.035 ≈ 28.6. 4% → ×25, 3.33% → ×30, 3% → ×33."),
        quiz("fr-meng-pfau", T, 3, "Meng and Pfau (2011) tested the 4% rule on 25 emerging-market countries and found…",
            listOf("It's always safe", "Its safety varied widely by country", "It works better than in the US", "No data exists"), 1,
            "The 4% rule comes from an unusually good century for US markets. In emerging markets results were much less reliable, so a lower rate is prudent.",
            source = "Meng & Pfau, 2011"),
        concept("fr-kenya-lower", T, 3, "Why does Morph use ×30 (about 3.3%) for Kenya instead of ×25?",
            "Kenyan inflation has spiked into double digits before, the shilling can lose value fast, fees on local funds can be 1–2% a year, and emerging markets were less safe in research. A bigger buffer covers that.",
            source = "Meng & Pfau, 2011"),
        quiz("fr-real-yield", T, 3, "Your MMF pays about 7.9% after tax and inflation is about 6.8%. Living off the full 7.9% would…",
            listOf("Keep your capital safe", "Slowly shrink your real wealth", "Double your wealth", "Have no effect"), 1,
            "Only about 1.1% is real growth; the rest just keeps up with prices. Spend more than the real return and your buying power shrinks.",
            source = "KNBS CPI Sept 2026; MMF averages Oct 2026", timeSensitive = true),
        quiz("fr-years-calc", T, 3, "Need: Ksh 18M. Have: 0. Invest Ksh 40,000/month at 7% a year. About how long?",
            listOf("About 10 years", "About 19 years", "About 37 years", "About 5 years"), 1,
            "Ksh 40,000 a month at 7% grows to about Ksh 18M after roughly 19 years. Doubling the monthly amount cuts it to about 12."),
        concept("fr-pension-relief", T, 3, "How much of your pension contributions can reduce your taxable income in Kenya?",
            "Up to Ksh 30,000 a month (Ksh 360,000 a year) into a registered pension or provident fund, since the Tax Laws (Amendment) Act 2024. At the 30% band, Ksh 30,000 saved could cut tax by up to Ksh 9,000 a month.",
            source = "Tax Laws (Amendment) Act 2024; RBA", timeSensitive = true),
        quiz("fr-nssf-2026", T, 3, "From February 2026, the most an employee pays into NSSF each month is about…",
            listOf("Ksh 200", "Ksh 1,080", "Ksh 6,480", "Ksh 12,960"), 2,
            "6% of pensionable pay up to Ksh 108,000 = Ksh 6,480, matched by the employer (Ksh 12,960 together). NSSF alone rarely funds freedom.",
            source = "NSSF Act 2013 Phase 4; KPMG, 2026", timeSensitive = true,
            tryThis = "Check your NSSF statement on the NSSF app."),
        quiz("fr-tax-free-exit", T, 3, "Since Dec 2024, when are withdrawals from a registered Kenyan pension scheme tax-exempt?",
            listOf("At retirement age, ill health, or after 20+ years in the scheme", "Never", "Only below age 40", "Only for NSSF"), 0,
            "The Tax Laws (Amendment) Act 2024 exempts these cases. Early cash-outs outside them can still be taxed, and lose decades of compounding.",
            source = "Tax Laws (Amendment) Act 2024", timeSensitive = true),
        concept("fr-runway-founder", T, 3, "How do freedom savings help someone who wants to start a business within a year?",
            "Runway (months of costs covered) buys time for the business to find customers without panic borrowing. A common aim is 6–12 months of personal costs saved before leaving a job, kept separate from business capital."),
        you("fr-you-gap", T, 3, "Your yearly spend is {spend_year} and your savings rate is {savings_rate}. Which one could you move by 5 points this quarter?",
            "Both shrink the time to freedom: spending lowers the target, saving speeds the climb. Pick the easier lever first.",
            tryThis = "Set a budget for your biggest category.", action = Action.BUDGETS, signals = setOf(Signal.SAVING_LOW)),

        // ── Level 4: Shark ──
        quiz("fr-sequence-num", T, 4, "Two retirees average the same return over 30 years. One hits −30% in year 1, the other in year 25. Who is worse off?",
            listOf("The year-1 crash", "The year-25 crash", "They end the same", "Neither, averages decide"), 0,
            "Withdrawing during an early crash sells many units cheaply, and they never recover. That's sequence-of-returns risk."),
        concept("fr-buckets", T, 4, "What is the \"bucket strategy\" for living off investments?",
            "Bucket 1: 1–2 years of spending in cash/MMF. Bucket 2: 3–7 years in bonds and T-bills. Bucket 3: the rest in growth assets. Spend from bucket 1 and refill it from the others in good years, so you never sell shares in a crash."),
        quiz("fr-refill", T, 4, "Shares just fell 25%. Your cash bucket is running low. The bucket approach says refill from…",
            listOf("Shares, immediately", "The bond bucket", "A loan", "Fuliza"), 1,
            "Bonds hold steadier in most crashes, so spend them and give shares time to recover. Refill bonds from shares after a good year."),
        quiz("fr-guardrails", T, 4, "Guyton and Klinger's \"guardrails\" (2006) let retirees start higher than 4% by…",
            listOf("Cutting spending a bit after bad years, raising it after good ones", "Holding only cash", "Never adjusting for inflation", "Borrowing in crashes"), 0,
            "Flexible rules respond to markets: if withdrawals rise too high as a % of the portfolio, trim about 10%. Flexibility buys a higher starting rate.",
            source = "Guyton & Klinger, Journal of Financial Planning, 2006"),
        concept("fr-drawdown-order", T, 4, "In what order do many planners draw down different pots in retirement?",
            "Usually: cash buffer and taxable savings first, then tax-advantaged pension money, letting it grow longer. In Kenya, pension exits after retirement age are tax-exempt, so the order is often driven by access rules, fees and income needs."),
        quiz("fr-inflation-retire", T, 4, "Spending of Ksh 600,000 a year today, with 6% inflation, costs about how much in 20 years?",
            listOf("Ksh 720,000", "Ksh 1.2M", "Ksh 1.9M", "Ksh 3.6M"), 2,
            "600,000 × 1.06^20 ≈ Ksh 1.92M. Your plan must grow income with prices; a fixed income loses about two-thirds of its value."),
        concept("fr-health", T, 4, "Why is healthcare a special risk in a freedom plan?",
            "Medical costs often rise faster than general inflation and peak in old age, when employer cover is gone. Plan for insurance into retirement. Since Dec 2024, contributions to a registered post-retirement medical fund are deductible up to Ksh 15,000 a month.",
            source = "Tax Laws (Amendment) Act 2024", timeSensitive = true),
        concept("fr-black-tax", T, 4, "How do you plan for \"black tax\" (supporting family) on the path to freedom?",
            "Make it a line in the budget, not a surprise. Agree amounts, give for school fees or health directly, and help family build their own income. Budgeted support is generosity; unbudgeted support can stall your freedom for years."),
        quiz("fr-black-tax-cost", T, 4, "Sending Ksh 15,000 a month to family for 20 years, instead of investing it at 5% real, costs your future self about…",
            listOf("Ksh 3.6M", "Ksh 6.2M", "Ksh 1.8M", "Ksh 15M"), 1,
            "15,000 × 240 = Ksh 3.6M given, which would have grown to about Ksh 6.2M. It may be worth every shilling; just plan it knowingly."),
        quiz("fr-glidepath", T, 4, "Kitces and Pfau (2014) found that, to blunt sequence risk, a retiree's share allocation can…",
            listOf("Start lower and rise over retirement", "Stay at 100% forever", "Drop to zero at 60", "Change daily"), 0,
            "A \"rising equity glidepath\" holds fewer shares in the risky early years, when a crash hurts most, and more later.",
            source = "Pfau & Kitces, Journal of Financial Planning, 2014"),
        concept("fr-cape-swr", T, 4, "Why might a safe withdrawal rate depend on how expensive shares are when you start?",
            "Historically, retiring when share prices were high relative to earnings (high CAPE ratio) led to lower future returns and worse outcomes. Starting when shares are cheap allowed higher withdrawals. Valuation is a sequence-risk clue."),
        quiz("fr-longevity", T, 4, "Retiring at 45 instead of 60 mostly changes the plan because…",
            listOf("The money must last 15+ more years", "Taxes disappear", "Inflation stops", "Returns double"), 0,
            "Longer retirements need lower withdrawal rates: research shows rates safe for 30 years can fail over 50–60 years."),

        // ── Level 5: Legend ──
        quiz("fr-kenya-coverage", T, 5, "Roughly what share of Kenya's labour force is covered by a registered retirement scheme?",
            listOf("About 10%", "About 26%", "About 60%", "About 85%"), 1,
            "The RBA reported about 26.5% (over 7.5M people) in 2025, targeting 34% by 2029. Most informal workers, about 84% of the workforce, have no pension.",
            source = "RBA, 2025; KNBS", timeSensitive = true),
        concept("fr-kenya-gap", T, 5, "What does Kenya's low pension coverage mean for your own freedom plan?",
            "Most Kenyans must self-fund old age through savings, assets, business and family. Even covered workers often withdraw early when changing jobs. Assume you'll be your own pension fund, and treat NSSF as a floor, not a plan.",
            source = "RBA; Nation, 2025"),
        quiz("fr-pension-split", T, 5, "At retirement from a Kenyan pension (not provident) fund, members can usually take up to…",
            listOf("One-third as cash, the rest as income", "100% as cash", "Nothing until 70", "Half as cash"), 0,
            "The other two-thirds buys an annuity or goes into an income drawdown fund. Provident funds allow full cash withdrawal.",
            source = "Retirement Benefits Act; RBA", timeSensitive = true),
        concept("fr-annuity", T, 5, "What is an annuity, and what risk does it remove?",
            "You hand an insurer a lump sum; it pays you an income for life. It removes longevity risk (outliving your money), but you give up access to the capital, and a fixed annuity loses value to inflation."),
        concept("fr-annuity-puzzle", T, 5, "What is the \"annuity puzzle\"?",
            "Menahem Yaari (1965) showed that, under simple assumptions, retirees should turn savings into annuities. Yet few do, worldwide. Reasons: wanting to leave money to family, health shocks, distrust of insurers and fear of dying early.",
            source = "Yaari, Review of Economic Studies, 1965"),
        concept("fr-die-zero", T, 5, "What is Bill Perkins's \"Die With Zero\" (2020) argument?",
            "Money is for experiences, and many people die with far more than they needed. He suggests planning to spend down your wealth, giving to family while alive, and timing experiences to your health and age."),
        quiz("fr-ern", T, 5, "Karsten Jeske's \"Early Retirement Now\" withdrawal series found that for 50–60 year retirements…",
            listOf("4% is always fine", "About 3.25–3.5% is much safer than 4%", "10% works", "Withdrawal rate doesn't matter"), 1,
            "Using US data from 1871, longer horizons made 4% fail noticeably more often, especially when starting with expensive shares.",
            source = "Early Retirement Now, SWR series, 2016–"),
        quiz("fr-life-cycle", T, 5, "Franco Modigliani's life-cycle hypothesis (1950s) says people try to…",
            listOf("Smooth spending over their lifetime", "Spend everything they earn each year", "Save only in old age", "Never borrow"), 0,
            "Save in high-earning years, spend down in old age. It helped earn him the 1985 Nobel Prize and underpins modern retirement planning.",
            source = "Modigliani & Brumberg, 1954"),
        concept("fr-modern-bengen", T, 5, "Has the 4% rule's creator changed his view?",
            "Yes. With more asset classes and data, William Bengen later raised his worst-case safe rate (\"SAFEMAX\") for US retirees to around 4.7% in his book A Richer Retirement. It still assumes US markets; Kenyan plans need extra caution.",
            source = "Bengen, A Richer Retirement; Bankrate"),
        quiz("fr-dms-freedom", T, 5, "Why do long-run return studies like Dimson–Marsh–Staunton matter for a freedom plan?",
            listOf("They show realistic real returns, about 5% for world shares", "They prove 15% real returns are normal", "They guarantee future returns", "They only cover Kenya"), 0,
            "Plans built on 12–15% real returns fail. World shares earned about 5.2% real a year since 1900; bonds about 1.7%. Use modest numbers.",
            source = "UBS Global Investment Returns Yearbook, 2025"),
        concept("fr-case-teacher", T, 5, "Case: a Nairobi teacher, 32, spends Ksh 40k a month, saves 35%, invests at 5% real. When might she reach ×30?",
            "Her number is about Ksh 14.4M. Saving 35% from zero at 5% real takes roughly 28 years. A side income that lifts saving to 50% cuts it to about 19 years: around age 51 instead of 60."),
        concept("fr-case-family", T, 5, "Case: a couple's assets reach ×30, but they support two parents. What should change in the plan?",
            "Add parents' support to yearly spending before multiplying. Ksh 20,000 a month of support adds Ksh 7.2M at ×30. Medical cover for parents, or a family pot shared with siblings, can cap this better than open-ended giving."),
        quiz("fr-flex-legend", T, 5, "Across the research (Bengen, Guyton–Klinger, ERN), what most raises the odds a freedom portfolio lasts?",
            listOf("Flexible spending and a modest starting rate", "Picking the best fund", "Holding all cash", "Retiring after a crash"), 0,
            "Being able to trim spending in bad years, plus a cautious start like ×30, does more than any product choice."),
    )
}
